/**
 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { extractSearchTokens } from "@/components/domain/search/query-syntax";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { Comment } from "@/types/comment";
import type { OrgId, Page } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index.
 *
 * Field-scoped syntax (`kind:`, `in:`, `project:`) is an `advanced_search`
 * feature (ADR 0007). Without the flag the whole query — colons included —
 * is free text and only issues are searched, whatever the caller asked for.
 * With the flag, tokens are pulled out with the same parser the dialog uses
 * for its hint line, and a `kind:`/`in:` token overrides the caller's
 * requested kinds (a `project:` token overrides the caller's `projectId`);
 * absent a token, the caller's own request is honoured.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  const tokens = advanced
    ? extractSearchTokens(input.q)
    : { text: input.q, kinds: [], projectId: null, unknownTokens: [] };

  const text = normaliseQuery(tokens.text);
  const kinds: SearchSubjectKind[] = !advanced
    ? ["issue"]
    : tokens.kinds.length > 0
      ? [...tokens.kinds]
      : input.kinds;
  const projectId = tokens.projectId ?? input.projectId;

  const page = await searchRepo.searchDocuments({
    ...input,
    q: text,
    kinds,
    projectId,
  });

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, text),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

function normaliseQuery(raw: string): string {
  return raw.trim().replace(/\s+/g, " ");
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (isArchived(issue)) {
    await removeFromIndex(orgId, "issue", issue.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

/**
 * Comments carry their issue's project id in the index (ADR 0007 rule 6), so
 * a `project:` scoped search finds comments too — the issue is re-read here
 * rather than trusted from the caller, the same discipline as every other
 * handler in this file.
 */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  if (isArchived(comment)) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue?.projectId ?? null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (isArchived(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.updated", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      const comment = await commentRepo.findCommentById(
        payload.orgId,
        payload.commentId,
      );
      if (comment) await indexComment(payload.orgId, comment);
    }),
    subscribe("comment.updated", async (payload) => {
      const comment = await commentRepo.findCommentById(
        payload.orgId,
        payload.commentId,
      );
      if (comment) await indexComment(payload.orgId, comment);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      const project = await projectRepo.findProjectById(
        payload.orgId,
        payload.projectId,
      );
      if (project) await indexProject(payload.orgId, project);
    }),
    subscribe("project.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "project", payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      if (payload.subjectKind !== "issue") return;
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.subjectId as Issue["id"],
      );
      if (issue) await indexIssue(payload.orgId, issue);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

function snippetAround(content: string, query: string): string {
  const at = content.toLowerCase().indexOf(query.toLowerCase());
  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);

  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
    end < content.length ? "…" : ""
  }`;
}

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";
import type { IssueStatus, IssuePriority } from "./issue";
import type { Role } from "./member";
import type { PlanId, LimitedResource } from "./billing";
import type { FeatureFlagKey } from "./feature-flag";

/** Fields present on every event payload; the bus stamps them on `emit`. */
export interface EventEnvelope {
  readonly orgId: OrgId;
  readonly actorId: UserId | null;
  readonly occurredAt: IsoTimestamp;
}

/**
 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 * only way to introduce one — services, jobs and the webhook dispatcher all
 * derive their handler signatures from it.
 */
export interface TaskflowEventMap {
  "project.created": EventEnvelope & {
    projectId: ProjectId;
    name: string;
    slug: string;
  };
  "project.archived": EventEnvelope & {
    projectId: ProjectId;
    issuesArchived: number;
  };
  "project.restored": EventEnvelope & { projectId: ProjectId };
  "issue.created": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    title: string;
    assigneeId: UserId | null;
    priority: IssuePriority;
  };
  "issue.updated": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    changedFields: readonly string[];
  };
  "issue.status_changed": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    from: IssueStatus;
    to: IssueStatus;
  };
  "issue.assigned": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    previousAssigneeId: UserId | null;
    assigneeId: UserId;
  };
  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
  "issue.overdue": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    dueAt: IsoTimestamp;
    assigneeId: UserId | null;
  };
  "comment.created": EventEnvelope & {
    commentId: CommentId;
    issueId: IssueId;
    mentionedUserIds: readonly UserId[];
  };
  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
  "member.invited": EventEnvelope & { email: string; role: Role };
  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
  "member.role_changed": EventEnvelope & {
    memberId: MemberId;
    from: Role;
    to: Role;
  };
  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
  "billing.limit_exceeded": EventEnvelope & {
    resource: LimitedResource;
    limit: number;
    used: number;
  };
  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
  "search.reindex_requested": EventEnvelope & {
    subjectKind: "issue" | "comment" | "project";
    subjectId: string;
  };
  "webhook.delivery_requested": EventEnvelope & {
    eventType: string;
    payload: Readonly<Record<string, unknown>>;
  };
}

export type TaskflowEventType = keyof TaskflowEventMap;

export type TaskflowEventPayload<K extends TaskflowEventType> =
  TaskflowEventMap[K];

/** A handler registered with `subscribe()`. May be async; errors are isolated. */
export type EventHandler<K extends TaskflowEventType> = (
  payload: TaskflowEventPayload<K>,
) => void | Promise<void>;

/** Returned by `subscribe()`; calling it removes the handler. */
export type Unsubscribe = () => void;

