1	/**
2	 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
5	 */
6	import { extractSearchTokens } from "@/components/domain/search/query-syntax";
7	import { subscribe } from "@/lib/event-bus";
8	import { isEnabled } from "@/lib/feature-flags";
9	import { assertCan } from "@/lib/permissions";
10	import { consumeRateLimit } from "@/lib/rate-limit";
11	import { isArchived } from "@/lib/soft-delete";
12	import { assertOrgScope } from "@/lib/tenant";
13	import * as commentRepo from "@/server/repositories/comment-repository";
14	import * as issueRepo from "@/server/repositories/issue-repository";
15	import * as orgRepo from "@/server/repositories/organization-repository";
16	import * as projectRepo from "@/server/repositories/project-repository";
17	import * as searchRepo from "@/server/repositories/search-repository";
18	import { orgResource } from "./_support";
19	import type { SearchQueryInput } from "@/schemas/search";
20	import type { SearchSubjectKind } from "@/server/repositories/search-repository";
21	import type { Comment } from "@/types/comment";
22	import type { OrgId, Page } from "@/types/common";
23	import type { Unsubscribe } from "@/types/event";
24	import type { Issue } from "@/types/issue";
25	import type { Actor } from "@/types/member";
26	import type { Project } from "@/types/project";
27	
28	export type SearchHit = {
29	  kind: SearchSubjectKind;
30	  id: string;
31	  title: string;
32	  snippet: string;
33	  href: string;
34	};
35	
36	/** Characters of surrounding context kept on either side of a match. */
37	const SNIPPET_RADIUS = 60;
38	
39	/** Token bucket protecting the index from query bursts. */
40	const SEARCH_QUERY_BUCKET = "search:query";
41	
42	/**
43	 * Runs a query against the denormalised index.
44	 *
45	 * Field-scoped syntax (`kind:`, `in:`, `project:`) is an `advanced_search`
46	 * feature (ADR 0007). Without the flag the whole query — colons included —
47	 * is free text and only issues are searched, whatever the caller asked for.
48	 * With the flag, tokens are pulled out with the same parser the dialog uses
49	 * for its hint line, and a `kind:`/`in:` token overrides the caller's
50	 * requested kinds (a `project:` token overrides the caller's `projectId`);
51	 * absent a token, the caller's own request is honoured.
52	 */
53	export async function search(
54	  actor: Actor,
55	  input: SearchQueryInput,
56	): Promise<Page<SearchHit>> {
57	  assertOrgScope(actor, input.orgId);
58	  assertCan(actor, "issue:read", orgResource(input.orgId));
59	
60	  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
61	  if (!verdict.allowed) {
62	    throw new Error(
63	      `Search rate limit reached; try again after ${verdict.resetAt}`,
64	    );
65	  }
66	
67	  const org = await orgRepo.findOrgById(input.orgId);
68	  const advanced = isEnabled("advanced_search", {
69	    orgId: input.orgId,
70	    userId: actor.userId,
71	    plan: org?.plan ?? "free",
72	    role: actor.role,
73	    overrides: org?.settings.enabledFlagOverrides,
74	  });
75	
76	  const tokens = advanced
77	    ? extractSearchTokens(input.q)
78	    : { text: input.q, kinds: [], projectId: null, unknownTokens: [] };
79	
80	  const text = normaliseQuery(tokens.text);
81	  const kinds: SearchSubjectKind[] = !advanced
82	    ? ["issue"]
83	    : tokens.kinds.length > 0
84	      ? [...tokens.kinds]
85	      : input.kinds;
86	  const projectId = tokens.projectId ?? input.projectId;
87	
88	  const page = await searchRepo.searchDocuments({
89	    ...input,
90	    q: text,
91	    kinds,
92	    projectId,
93	  });
94	
95	  return {
96	    items: page.items.map((row) => ({
97	      kind: row.subjectKind,
98	      id: row.subjectId,
99	      title: row.content.split("\n")[0] ?? row.subjectId,
100	      snippet: snippetAround(row.content, text),
101	      href: hrefFor(row.subjectKind, row.subjectId),
102	    })),
103	    nextCursor: page.nextCursor,
104	    total: page.total,
105	  };
106	}
107	
108	function normaliseQuery(raw: string): string {
109	  return raw.trim().replace(/\s+/g, " ");
110	}
111	
112	export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
113	  if (isArchived(issue)) {
114	    await removeFromIndex(orgId, "issue", issue.id);
115	    return;
116	  }
117	
118	  await searchRepo.upsertSearchDocument(
119	    orgId,
120	    "issue",
121	    issue.id,
122	    [issue.title, issue.description ?? ""].join("\n"),
123	    issue.projectId,
124	  );
125	}
126	
127	/**
128	 * Comments carry their issue's project id in the index (ADR 0007 rule 6), so
129	 * a `project:` scoped search finds comments too — the issue is re-read here
130	 * rather than trusted from the caller, the same discipline as every other
131	 * handler in this file.
132	 */
133	export async function indexComment(
134	  orgId: OrgId,
135	  comment: Comment,
136	): Promise<void> {
137	  if (isArchived(comment)) {
138	    await removeFromIndex(orgId, "comment", comment.id);
139	    return;
140	  }
141	
142	  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
143	  await searchRepo.upsertSearchDocument(
144	    orgId,
145	    "comment",
146	    comment.id,
147	    comment.body,
148	    issue?.projectId ?? null,
149	  );
150	}
151	
152	export async function indexProject(
153	  orgId: OrgId,
154	  project: Project,
155	): Promise<void> {
156	  if (isArchived(project)) {
157	    await removeFromIndex(orgId, "project", project.id);
158	    return;
159	  }
160	
161	  await searchRepo.upsertSearchDocument(
162	    orgId,
163	    "project",
164	    project.id,
165	    [project.name, project.description ?? ""].join("\n"),
166	    project.id,
167	  );
168	}
169	
170	export async function removeFromIndex(
171	  orgId: OrgId,
172	  subjectKind: SearchSubjectKind,
173	  subjectId: string,
174	): Promise<void> {
175	  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
176	}
177	
178	/**
179	 * Keeps the index in step with writes. Every handler re-reads the row rather
180	 * than trusting the event payload, so a partially-applied write can never be
181	 * indexed as if it had succeeded.
182	 */
183	export function registerSearchListeners(): Unsubscribe {
184	  const offs: Unsubscribe[] = [
185	    subscribe("issue.created", async (payload) => {
186	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
187	      if (issue) await indexIssue(payload.orgId, issue);
188	    }),
189	    subscribe("issue.updated", async (payload) => {
190	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
191	      if (issue) await indexIssue(payload.orgId, issue);
192	    }),
193	    subscribe("issue.archived", async (payload) => {
194	      await removeFromIndex(payload.orgId, "issue", payload.issueId);
195	    }),
196	    subscribe("comment.created", async (payload) => {
197	      const comment = await commentRepo.findCommentById(
198	        payload.orgId,
199	        payload.commentId,
200	      );
201	      if (comment) await indexComment(payload.orgId, comment);
202	    }),
203	    subscribe("comment.updated", async (payload) => {
204	      const comment = await commentRepo.findCommentById(
205	        payload.orgId,
206	        payload.commentId,
207	      );
208	      if (comment) await indexComment(payload.orgId, comment);
209	    }),
210	    subscribe("comment.deleted", async (payload) => {
211	      await removeFromIndex(payload.orgId, "comment", payload.commentId);
212	    }),
213	    subscribe("project.created", async (payload) => {
214	      const project = await projectRepo.findProjectById(
215	        payload.orgId,
216	        payload.projectId,
217	      );
218	      if (project) await indexProject(payload.orgId, project);
219	    }),
220	    subscribe("project.archived", async (payload) => {
221	      await removeFromIndex(payload.orgId, "project", payload.projectId);
222	    }),
223	    subscribe("search.reindex_requested", async (payload) => {
224	      const { orgId, subjectKind, subjectId } = payload;
225	      switch (subjectKind) {
226	        case "issue": {
227	          const issue = await issueRepo.findIssueById(
228	            orgId,
229	            subjectId as Issue["id"],
230	          );
231	          if (issue) await indexIssue(orgId, issue);
232	          else await removeFromIndex(orgId, "issue", subjectId);
233	          break;
234	        }
235	        case "comment": {
236	          const comment = await commentRepo.findCommentById(
237	            orgId,
238	            subjectId as Comment["id"],
239	          );
240	          if (comment) await indexComment(orgId, comment);
241	          else await removeFromIndex(orgId, "comment", subjectId);
242	          break;
243	        }
244	        case "project": {
245	          const project = await projectRepo.findProjectById(
246	            orgId,
247	            subjectId as Project["id"],
248	          );
249	          if (project) await indexProject(orgId, project);
250	          else await removeFromIndex(orgId, "project", subjectId);
251	          break;
252	        }
253	      }
254	    }),
255	  ];
256	
257	  return () => {
258	    for (const off of offs) off();
259	  };
260	}
261	
262	function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
263	  switch (kind) {
264	    case "issue":
265	      return `/issues/${subjectId}`;
266	    case "comment":
267	      return `/comments/${subjectId}`;
268	    case "project":
269	      return `/projects/${subjectId}`;
270	  }
271	}
272	
273	function snippetAround(content: string, query: string): string {
274	  const at = content.toLowerCase().indexOf(query.toLowerCase());
275	  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);
276	
277	  const start = Math.max(0, at - SNIPPET_RADIUS);
278	  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
279	  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
280	    end < content.length ? "…" : ""
281	  }`;
282	}
